"""The Firefox logo and mascot replacements generated by tools/nivora/generate_ui_artwork.py."""

import math
import re
import sys
import unittest
import xml.etree.ElementTree as ET
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT / "tools" / "nivora"))

import generate_ui_artwork as art  # noqa: E402
import generate_branding as gb  # noqa: E402

SVG = "{http://www.w3.org/2000/svg}"


class ArtworkTest(unittest.TestCase):
    def setUp(self):
        self.files = art.build()

    def test_committed_files_match_the_generator(self):
        for path, content in self.files.items():
            target = ROOT / "src" / path
            self.assertTrue(target.is_file(), f"{path} is missing; run generate_ui_artwork.py")
            self.assertEqual(target.read_text(encoding="utf-8"), content, f"{path} is stale")

    def test_files_are_well_formed_svg_with_the_expected_size(self):
        for path, (kind, width, height, fill, *rest) in art.ARTWORK.items():
            root = ET.fromstring(self.files[path])
            self.assertEqual(root.tag, SVG + "svg", path)
            if rest:
                self.assertEqual((root.get("width"), root.get("height")), (None, str(rest[0])), path)
            else:
                self.assertEqual((root.get("width"), root.get("height")), (str(width), str(height)), path)
            self.assertEqual(root.get("viewBox"), f"0 0 {width} {height}", path)

    def test_every_file_carries_the_license_header(self):
        for path, content in self.files.items():
            self.assertTrue(content.startswith("<!-- This Source Code Form is subject to the terms of the Mozilla Public"), path)

    def test_only_palette_colors_are_used(self):
        names = ("text-primary", "text-secondary", "text-muted", "separator", "separator-strong", "surface-raised")
        allowed = {gb.color(name) for name in names} | {"#fff", "#000"}
        for path, content in self.files.items():
            for found in re.findall(r"#[0-9a-fA-F]{3,6}\b", content):
                self.assertIn(found.lower(), allowed, f"{path}: {found} is not a palette color")

    def test_nothing_is_loaded_from_elsewhere(self):
        for path, content in self.files.items():
            self.assertNotRegex(content, r"(?i)(href=|url\((?!#)|<image|<script|<style|<use)", path)

    def test_the_replaced_artwork_names_the_firefox_logo_and_the_mascot(self):
        names = " ".join(art.ARTWORK)
        for needle in ("sidebar/firefox.svg", "window-firefox.svg", "share-firefox.svg", "kit-happy.svg", "kit-concerned.svg",
                       "fox-tail.svg", "fox-with-devices.svg", "fox-concern.svg"):
            self.assertIn(needle, names)

    def test_glyph_hole_stays_inside_the_disc(self):
        """With the even-odd rule a hole that pokes outside the disc would be painted."""
        for width, height in {(a[1], a[2]) for a in art.ARTWORK.values() if a[0] == "glyph"}:
            r = min(width, height) * 0.46
            hr, dx, dy = r * 0.74, r * 0.15, -r * 0.15
            self.assertLess(math.hypot(dx, dy) + hr, r, (width, height))


class PreviewTest(unittest.TestCase):
    def test_committed_previews_match_the_generator(self):
        for path, data in art.build_previews().items():
            target = ROOT / "src" / path
            self.assertTrue(target.is_file(), path)
            self.assertTrue(art.same_image(target.read_bytes(), data), f"{path} is stale")

    def test_previews_have_the_size_the_pane_expects_and_are_monochrome(self):
        from PIL import Image
        import io

        for path, data in art.build_previews().items():
            image = Image.open(io.BytesIO(data)).convert("RGB")
            self.assertEqual(image.size, art.PREVIEW_SIZE, path)
            colored = [c for _, c in image.getcolors(maxcolors=1 << 20) if max(c) - min(c) > 1]
            self.assertEqual(colored, [], f"{path} contains colors outside the neutral palette")

    def test_the_three_layouts_differ(self):
        data = list(art.build_previews().values())
        self.assertEqual(len({d for d in data}), 3)


class CheckModeTest(unittest.TestCase):
    def test_check_reports_a_modified_file(self):
        import tempfile

        with tempfile.TemporaryDirectory() as tmp:
            src = Path(tmp)
            self.assertEqual(art.main(["--src", str(src)]), 0)
            self.assertEqual(art.main(["--check", "--src", str(src)]), 0)
            victim = src / next(iter(art.ARTWORK))
            victim.write_text(victim.read_text(encoding="utf-8") + "<!-- edited -->\n", encoding="utf-8")
            self.assertEqual(art.main(["--check", "--src", str(src)]), 1)


if __name__ == "__main__":
    unittest.main()
